package cl.acis.catalogos.controller;
import cl.acis.catalogos.config.ActorHeaders; import cl.acis.catalogos.dto.*; import cl.acis.catalogos.service.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest({CatalogoController.class,FotoController.class}) class CatalogoControllerTest{@Autowired MockMvc mvc;@MockBean CatalogoService catalogos;@MockBean FotoService fotos;@MockBean ActorHeaders headers;
 @Test void crearClienteValidoResponde200()throws Exception{when(headers.leer(any())).thenReturn(new ActorHeaders.Actor(1L,"ADMINISTRADOR"));when(catalogos.crearCliente(any())).thenReturn(new ClienteResponse(1L,"Clima","76.543.210-3",null,"a@a.cl",null,null,null,true));mvc.perform(post("/api/clientes").header("X-Usuario-Id","1").header("X-Usuario-Rol","ADMINISTRADOR").contentType(MediaType.APPLICATION_JSON).content("{\"razonSocial\":\"Clima\",\"rut\":\"76.543.210-3\",\"correo\":\"a@a.cl\"}")).andExpect(status().isOk());}
 @Test void clientesSinHeaderResponde401()throws Exception{when(headers.leer(any())).thenThrow(new cl.acis.catalogos.exception.NoAutorizadoException("Faltan headers"));mvc.perform(get("/api/clientes")).andExpect(status().isUnauthorized());}
 @Test void clienteConCorreoInvalidoResponde400()throws Exception{when(headers.leer(any())).thenReturn(new ActorHeaders.Actor(1L,"ADMINISTRADOR"));mvc.perform(post("/api/clientes").header("X-Usuario-Id","1").header("X-Usuario-Rol","ADMINISTRADOR").contentType(MediaType.APPLICATION_JSON).content("{\"razonSocial\":\"Clima\",\"rut\":\"76.543.210-3\",\"correo\":\"correo-invalido\"}")).andExpect(status().isBadRequest());}
}
